/* KABAURIA Kaos Tambang - Affiliate Portal (tersambung Supabase) */
const APP_VERSION='3.3';
/* Tampilkan setiap error di layar (bukan diam-diam) agar mudah dilacak */
function showFatal(m){try{let b=document.getElementById('fatalBanner');if(!b){b=document.createElement('div');b.id='fatalBanner';b.style.cssText='position:fixed;left:0;right:0;bottom:0;z-index:99999;background:#7f1d1d;color:#fff;padding:10px 14px;font:13px/1.4 system-ui,sans-serif;white-space:pre-wrap;cursor:pointer';b.title='Klik untuk menutup';b.onclick=()=>b.remove();document.body.appendChild(b)}b.textContent='Terjadi kesalahan (v'+APP_VERSION+'): '+m}catch(_){}}
window.addEventListener('error',e=>showFatal((e.message||'error')+(e.filename?' ['+e.filename.split('/').pop()+':'+e.lineno+']':'')));
window.addEventListener('unhandledrejection',e=>showFatal(String((e.reason&&e.reason.message)||e.reason)));
const $=id=>document.getElementById(id);
const mkStore=n=>{try{const t=window[n];t.setItem('_t','1');t.removeItem('_t');return t}catch(e){const m={};return{getItem:k=>k in m?m[k]:null,setItem:(k,v)=>{m[k]=String(v)},removeItem:k=>{delete m[k]}}}};
const SS=mkStore('sessionStorage');
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const plusMonths=(date,months)=>{const d=new Date((date||today())+'T12:00:00');const day=d.getDate();d.setMonth(d.getMonth()+months);if(d.getDate()<day)d.setDate(0);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const moneySigned=n=>Number(n)<0?'−'+money(-Number(n)):money(n);
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

/* ---------- Supabase ---------- */
/* Membaca konfigurasi: format `const SUPABASE_URL=...` ATAU `window.KABAURIA_CONFIG={SUPABASE_URL,SUPABASE_ANON_KEY}` */
const _cfg=window.KABAURIA_CONFIG||{};
const CFG_URL=String(typeof SUPABASE_URL!=='undefined'?SUPABASE_URL:(_cfg.SUPABASE_URL||_cfg.url||'')).trim();
const CFG_KEY=String(typeof SUPABASE_ANON_KEY!=='undefined'?SUPABASE_ANON_KEY:(_cfg.SUPABASE_ANON_KEY||_cfg.anonKey||'')).trim();
const CFG_EMAIL_BASE=String(_cfg.AFFILIATE_EMAIL_BASE||(typeof AFFILIATE_EMAIL_BASE!=='undefined'?AFFILIATE_EMAIL_BASE:'')||'kabauria.affiliate@gmail.com').trim();
/* Affiliate login pakai USERNAME. Di Supabase Auth username diubah jadi email tersembunyi: nama+username@domain */
const userToEmail=u=>{const p=CFG_EMAIL_BASE.split('@');return p[0]+'+'+String(u).trim().toLowerCase()+'@'+p[1]};
let cfgWhy='';
if(!CFG_URL&&!CFG_KEY)cfgWhy='File config.js tidak terbaca atau tidak ada di GitHub.';
else if(/ISI_/.test(CFG_URL)||/ISI_/.test(CFG_KEY))cfgWhy='config.js masih berisi tulisan contoh (ISI_...). Ganti dengan URL dan anon key dari Supabase, lalu upload ulang ke GitHub.';
else if(!/^https:\/\/[a-z0-9-]+\.supabase\.(co|in)\/?$/i.test(CFG_URL))cfgWhy='SUPABASE_URL salah format. Harus seperti https://abcdefgh.supabase.co (tanpa /rest/v1/ atau tambahan lain). Isi sekarang: '+CFG_URL.slice(0,60);
else if(CFG_KEY.length<20)cfgWhy='SUPABASE_ANON_KEY terlalu pendek / belum lengkap.';
else if(!window.supabase)cfgWhy='Library Supabase gagal dimuat (cek koneksi internet atau pemblokir iklan).';
const cfgOk=!cfgWhy;
let sb=null;
if(cfgOk){try{sb=window.supabase.createClient(CFG_URL,CFG_KEY)}catch(e){cfgWhy='Gagal membuat sambungan: '+e.message}}

/* ---------- State (cache dari Supabase) ---------- */
let db={settings:{commissionMode:'fixed',commissionValue:10000,payments:{qris:{enabled:false,image:''},transfer:{enabled:false,bank:'',number:'',holder:''},cash:{enabled:true,note:''}}},products:[],affiliates:[],orders:[],commissions:[],payouts:[],audit:[]};
let session={admin:false,aff:''};
let variantDraft=[],editingImage='',orderContext=null,activeView='catalog',activeAdminView='overview',loading=true,editGroup=null;

/* ---------- Mapper baris database -> objek aplikasi ---------- */
const mapProduct=p=>({id:p.id,name:p.name,category:p.category,price:Number(p.price),type:p.type,description:p.description,imageData:'',imageUrl:p.image_url||'',images:(p.image_urls&&p.image_urls.length)?p.image_urls:(p.image_url?[p.image_url]:[]),commissionMode:p.commission_mode,commissionValue:Number(p.commission_value),createdAt:new Date(p.created_at).getTime(),variants:(p.product_variants||[]).slice().sort((a,b)=>a.sort_order-b.sort_order).map(v=>({id:v.id,group:v.group_name,type:v.type,color:v.color,size:v.size,image:v.image_url||'',stock:v.stock}))});
const mapAff=a=>({id:a.id,userId:a.user_id,username:a.username||'',name:a.name,email:a.email,code:a.code,status:a.status,startDate:a.start_date,endDate:a.end_date,commissionMode:a.commission_mode,commissionValue:Number(a.commission_value),deletedAt:a.deleted_at,createdAt:new Date(a.created_at).getTime()});
const mapOrder=o=>({id:o.id,orderNo:o.order_no,productId:o.product_id,productName:o.product_name,thumbUrl:o.thumb_url,qty:o.qty,unitPrice:Number(o.unit_price),total:Number(o.total),customerName:o.customer_name,phone:o.phone,address:o.address,note:o.note,paymentMethod:o.payment_method,source:o.source,affiliateId:o.affiliate_id,affiliateCode:o.affiliate_code,status:o.status,stockDeducted:o.stock_deducted,receivedAt:o.received_at,adminNote:o.admin_note,claimedBy:o.claimed_by,createdAt:o.created_at,items:(o.order_items||[]).map(i=>({variantId:i.variant_id,label:i.label,qty:i.qty}))});
const mapAffOrder=o=>({id:o.id,orderNo:o.order_no,productName:o.product_name,thumbUrl:o.thumb_url,qty:o.qty,total:Number(o.total),status:o.status,customerName:o.customer_name,createdAt:o.created_at,itemsText:o.items_text||'',items:[],affiliateId:session.aff,productId:null});
const mapCom=c=>({id:c.id,affiliateId:c.affiliate_id,orderId:c.order_id,orderNo:c.order_no,amount:Number(c.amount),paidAmount:Number(c.paid_amount),correctionOutstanding:Number(c.correction_outstanding),status:c.status,note:c.note,createdAt:c.created_at,paidAt:c.paid_at});
const mapPayout=p=>({id:p.id,affiliateId:p.affiliate_id,amount:Number(p.gross_amount),correctionDeducted:Number(p.correction_deducted),netAmount:Number(p.net_amount),method:p.method,note:p.note,date:p.created_at});

async function loadAll(){
 if(!sb)return;
 const q=[sb.from('products').select('*, product_variants(*)').order('created_at',{ascending:false}),sb.rpc('get_payment_info')];
 if(session.admin){q.push(sb.from('settings').select('*').eq('id',1).single(),sb.from('affiliates').select('*').order('created_at',{ascending:false}),sb.from('orders').select('*, order_items(*)').order('created_at',{ascending:false}),sb.from('commissions').select('*').order('created_at',{ascending:false}),sb.from('payouts').select('*').order('created_at',{ascending:false}),sb.from('audit_log').select('*').order('created_at',{ascending:false}).limit(100))}
 else if(session.aff){q.push(sb.from('affiliates').select('*').eq('id',session.aff),sb.from('affiliate_orders').select('*').order('created_at',{ascending:false}),sb.from('commissions').select('*').order('created_at',{ascending:false}),sb.from('payouts').select('*').order('created_at',{ascending:false}))}
 const r=await Promise.all(q);const bad=r.find(x=>x.error);if(bad)throw bad.error;
 db.products=(r[0].data||[]).map(mapProduct);
 if(r[1].data)db.settings.payments=r[1].data;
 db.affiliates=[];db.orders=[];db.commissions=[];db.payouts=[];db.audit=[];
 if(session.admin){const s=r[2].data;db.settings.commissionMode=s.commission_mode;db.settings.commissionValue=Number(s.commission_value);db.settings.payments=s.payments;
  db.affiliates=r[3].data.map(mapAff);db.orders=r[4].data.map(mapOrder);db.commissions=r[5].data.map(mapCom);db.payouts=r[6].data.map(mapPayout);db.audit=r[7].data.map(a=>({action:a.action,detail:a.detail,date:a.created_at}))}
 else if(session.aff){db.affiliates=r[2].data.map(mapAff);db.orders=r[3].data.map(mapAffOrder);db.commissions=r[4].data.map(mapCom);db.payouts=r[5].data.map(mapPayout)}
}
async function refresh(){try{await loadAll()}catch(e){alert('Gagal memuat data: '+(e.message||e))}loading=false;try{renderAll()}catch(e){showFatal('Gagal menampilkan halaman: '+(e.message||e));console.error(e)}}
async function refreshRole(){
 session.admin=false;session.aff='';
 const {data}=await sb.auth.getSession();const user=data.session?.user;if(!user)return;
 /* dua pemeriksaan dijalankan bersamaan (hemat 1x tunggu jaringan) */
 const [ad,af]=await Promise.all([sb.from('admins').select('user_id').eq('user_id',user.id).maybeSingle(),sb.from('affiliates').select('id').eq('user_id',user.id).maybeSingle()]);
 if(ad.data){session.admin=true;return}
 if(af.data)session.aff=af.data.id}
const adminLog=(a,d)=>sb.rpc('admin_log',{p_action:a,p_detail:d});
async function call(name,args){const {data,error}=await sb.rpc(name,args);if(error){alert(error.message);return{ok:false}}await refresh();return{ok:true,data}}
async function uploadImage(dataUrl,folder){const blob=await (await fetch(dataUrl)).blob();const path=folder+'/'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8)+'.jpg';const {error}=await sb.storage.from('media').upload(path,blob,{contentType:'image/jpeg',cacheControl:'31536000'});if(error)throw error;return sb.storage.from('media').getPublicUrl(path).data.publicUrl}

/* ---------- Helper tampilan ---------- */
function activeStatus(a){if(a.deletedAt||a.status==='deleted')return 'deleted';if(a.status==='disabled')return 'disabled';if(a.status==='pending')return 'pending';if(a.endDate&&a.endDate<today())return 'expired';return 'active'}
function statusLabel(s){return ({active:'Aktif',pending:'Menunggu persetujuan',disabled:'Dinonaktifkan',expired:'Kedaluwarsa',deleted:'Dihapus',awaiting_payment:'Menunggu pembayaran',payment_claimed:'Menunggu verifikasi admin',paid:'Dibayar · menunggu paket diterima',completed:'Paket diterima',returned:'Diretur',stock_issue:'Perlu penyelesaian admin',cancelled:'Dibatalkan',pending_review:'Komisi tertunda',approved:'Disetujui · siap dibayar',paid_out:'Dibayarkan',reversed:'Dikoreksi'})[s]||s}
function badge(s){const cls=['active','approved','completed','paid_out'].includes(s)?'green':['paid'].includes(s)?'blue':['pending','awaiting_payment','payment_claimed','pending_review'].includes(s)?'amber':['expired','disabled','deleted','cancelled','reversed'].includes(s)?'red':['stock_issue'].includes(s)?'blue':'';return `<span class="badge ${cls}">${esc(statusLabel(s))}</span>`}
function stock(p){return (p.variants||[]).reduce((n,v)=>n+Math.max(0,Number(v.stock)||0),0)}
function productImg(p){return productImgs(p)[0]||''}
const MAX_IMG=5;let productImages=[];
function productImgs(p){if(!p)return[];if(p.images&&p.images.length)return p.images.filter(Boolean);const one=p.imageData||p.imageUrl;return one?[one]:[]}
function galleryHtml(p){const im=productImgs(p);if(!im.length)return '<div class="pgal"><div class="pgal-empty">Foto produk</div></div>';return '<div class="pgal"><div class="pgal-track" id="pgalTrack">'+im.map(s=>'<img data-zoom="'+esc(s)+'" src="'+esc(s)+'" alt="" title="Klik untuk memperbesar">').join('')+'</div>'+(im.length>1?'<div class="pgal-count" id="pgalCount">1/'+im.length+'</div><div class="pgal-dots" id="pgalDots">'+im.map((_,i)=>'<button type="button" data-pgal="'+i+'" class="'+(i?'':'on')+'" aria-label="Foto '+(i+1)+'"></button>').join('')+'</div>':'')+'</div>'}
document.addEventListener('scroll',e=>{const t=e.target;if(!t||t.id!=='pgalTrack')return;const n=t.children.length,i=Math.max(0,Math.min(n-1,Math.round(t.scrollLeft/Math.max(1,t.clientWidth))));const c=document.getElementById('pgalCount');if(c)c.textContent=(i+1)+'/'+n;document.querySelectorAll('#pgalDots button').forEach((b,k)=>b.classList.toggle('on',k===i))},true);
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-pgal]');if(!b)return;const t=document.getElementById('pgalTrack');if(t)t.scrollTo({left:t.clientWidth*Number(b.dataset.pgal),behavior:'smooth'})});
function renderImageList(){const L=$('pImageList');L.innerHTML=productImages.map((s,i)=>'<div class="pimg"><img src="'+esc(s)+'" alt="">'+(i===0?'<span class="pmain">Utama</span>':'')+'<button type="button" class="danger" data-delimg="'+i+'" aria-label="Hapus foto">✕</button></div>').join('');L.querySelectorAll('[data-delimg]').forEach(b=>b.onclick=()=>{productImages.splice(Number(b.dataset.delimg),1);renderImageList()});const n=productImages.length;$('pImageStatus').innerHTML=n>1?'<div class="notice" style="margin-top:8px">'+n+' foto dipilih. Di jendela pesan, foto tampil sebagai galeri yang bisa digeser. Foto pertama menjadi foto utama.</div>':n===1?'1 foto. Minimal 1, maksimal '+MAX_IMG+'.':'Belum ada foto. Minimal 1, maksimal '+MAX_IMG+'.'}
async function addProductImages(files,max){const fs=[...files].filter(f=>f.type.startsWith('image/'));if(!fs.length)return;const room=MAX_IMG-productImages.length;if(room<=0){alert('Maksimal '+MAX_IMG+' foto. Hapus salah satu foto dulu.');return}if(fs.length>room)alert('Maksimal '+MAX_IMG+' foto. Hanya '+room+' foto pertama yang dipakai.');for(const f of fs.slice(0,room)){try{productImages.push(await compressImage(f,max))}catch(_){alert('Gagal memproses salah satu gambar.')}}renderImageList();if(productImages.length>1)alert('Anda memiliki '+productImages.length+' foto produk. Foto akan tampil sebagai galeri geser untuk pelanggan.')}

function getAffiliate(id){return db.affiliates.find(a=>a.id===id)}
function getProduct(id){return db.products.find(p=>p.id===id)}
function ruleLabel(mode,value){return mode==='percent'?(Number(value)||0)+'%':money(value)+' / pcs'}
function affiliateCommLabel(a){return a&&a.commissionMode&&a.commissionMode!=='default'?ruleLabel(a.commissionMode,a.commissionValue):'Default ('+ruleLabel(db.settings.commissionMode,db.settings.commissionValue)+')'}
const baseUrl=()=>location.href.split('#')[0].split('?')[0];
const payLabel=k=>({qris:'QRIS',transfer:'Transfer bank',cash:'Tunai'})[k]||'-';
const orderItems=o=>o.items||[];
const itemsText=o=>o.itemsText||orderItems(o).map(i=>i.label+' × '+i.qty).join(', ');
const paidOf=c=>c.status==='paid_out'?c.amount:(Number(c.paidAmount)||0);
const remainOf=c=>c.status==='approved'?Math.max(0,c.amount-(Number(c.paidAmount)||0)):0;
function copyText(t,msg){const ok=()=>alert(msg||'Disalin.');if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t).then(ok).catch(()=>alert('Salin manual: '+t));else{const x=document.createElement('textarea');x.value=t;document.body.appendChild(x);x.select();try{document.execCommand('copy');ok()}catch(e){alert('Salin manual: '+t)}x.remove()}}
function orderThumbUrl(o){const p=getProduct(o.productId);if(p){const it=orderItems(o)[0];const v=it&&p.variants.find(x=>x.id===it.variantId);const src=v?.image||productImg(p);if(src)return src}return o.thumbUrl||''}
function orderThumb(o,size=48){const src=orderThumbUrl(o);return src?`<img data-zoom="${esc(src)}" src="${esc(src)}" alt="" title="Klik untuk memperbesar" style="width:${size}px;height:${size}px;object-fit:cover;border-radius:8px;border:1px solid var(--line);flex:0 0 auto;cursor:zoom-in">`:`<div class="no-photo muted" style="width:${size}px;height:${size}px;border:1px dashed var(--line);border-radius:8px;font-size:9px;flex:0 0 auto">Foto</div>`}
function affBalance(id){const c=db.commissions.filter(x=>x.affiliateId===id);const ready=c.reduce((n,x)=>n+remainOf(x),0);const debt=c.filter(x=>x.status==='reversed').reduce((n,x)=>n+(Number(x.correctionOutstanding)||0),0);return{ready,debt,net:ready-debt,balance:Math.max(0,ready-debt),pending:c.filter(x=>x.status==='pending_review').reduce((n,x)=>n+x.amount,0),paid:db.payouts.filter(p=>p.affiliateId===id).reduce((n,p)=>n+p.netAmount,0)}}

function renderAll(){renderCatalog();renderAffiliatePicker();renderAdmin()}
function setView(view){activeView=view;document.querySelectorAll('#mainTabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));['catalog','affiliate','admin'].forEach(v=>$('view-'+v).classList.toggle('hidden',v!==view));if(view==='affiliate')renderAffiliateDashboard();if(view==='admin')renderAdmin()}
document.querySelectorAll('#mainTabs button').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));


/* ---------- Mode tampilan berdasarkan link ----------
   ?ref=KODE atau ?sales=admin  -> katalog saja (untuk pelanggan)
   ?page=affiliate              -> dashboard affiliate saja (link login affiliate)
   ?page=admin                  -> dashboard admin saja
   tanpa parameter              -> semua tab */
const QS=new URLSearchParams(location.search);
const MODE=(QS.get('ref')||QS.get('sales')==='admin')?'catalog':(QS.get('page')==='affiliate'?'affiliate':(QS.get('page')==='admin'?'admin':'all'));
function applyMode(){if(MODE==='all')return;$('mainTabs').classList.add('hidden');setView(MODE)}
const affLoginLink=()=>baseUrl()+'?page=affiliate';

/* ---------- Katalog & pemesanan ---------- */
function renderCatalog(){
 const term=$('search').value.trim().toLowerCase(),cat=$('catFilter').value,sort=$('sort').value;
 const cats=[...new Set(db.products.map(p=>p.category))].sort();const old=$('catFilter').value;
 $('catFilter').innerHTML='<option value="">Semua kategori</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if(cats.includes(old))$('catFilter').value=old;
 let list=db.products.filter(p=>(!cat||p.category===cat)&&[p.name,p.category,p.type,p.description].join(' ').toLowerCase().includes(term));
 if(sort==='low')list.sort((a,b)=>a.price-b.price);else if(sort==='high')list.sort((a,b)=>b.price-a.price);else list.sort((a,b)=>b.createdAt-a.createdAt);
 $('catalogCount').textContent=list.length+' produk';$('catalogEmpty').classList.toggle('hidden',list.length>0);
 $('catalogEmpty').textContent=!sb?'Belum tersambung ke Supabase.':loading?'Memuat katalog...':'Belum ada produk. Admin dapat menambahkan produk melalui dashboard admin.';
 $('catalogGrid').innerHTML=list.map(p=>`<article class="product"><div class="photo" id="ph_${p.id}">${productImg(p)?`<img src="${esc(productImg(p))}" alt="${esc(p.name)}" loading="lazy">`:'<div class="no-photo">Foto produk</div>'}<span class="stock-badge">${stock(p)>0?'Stok tersedia':'Stok habis'}</span></div><div class="pbody"><div class="muted">${esc(p.category)}</div><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}</div><div class="muted">${esc(p.description||p.type)}</div><input type="hidden" class="catalog-variant" data-product="${p.id}" value="${Math.max(0,p.variants.findIndex(v=>v.stock>0))}"><button data-buy="${p.id}" ${stock(p)<=0?'disabled':''}>Pesan produk</button></div></article>`).join('');
 document.querySelectorAll('[data-buy]').forEach(b=>b.addEventListener('click',()=>openOrder(b.dataset.buy)));
}
$('search').addEventListener('input',renderCatalog);$('catFilter').addEventListener('change',renderCatalog);$('sort').addEventListener('change',renderCatalog);
function openOrder(productId){const p=getProduct(productId);if(!p)return;if(!p.variants.some(v=>v.stock>0)){alert('Stok habis.');return}const sel=document.querySelector(`.catalog-variant[data-product="${productId}"]`);const pre=Number(sel?.value)||0;orderContext={productId,qty:p.variants.map((x,i)=>i===pre&&x.stock>0?1:0)};$('oProductId').value=productId;
 $('orderProductSummary').innerHTML=`${galleryHtml(p)}<div class="ohead"><strong>${esc(p.name)}</strong><div class="oprice">${money(p.price)} <span class="muted">/ pcs</span></div></div><label class="muted">Pilih variasi dan jumlah (sesuai stok)</label>${vGroupsHtml(p,(x,i)=>`<div class="rowline" style="margin-top:6px">${(x.image||productImg(p))?`<img data-zoom="${esc(x.image||productImg(p))}" src="${esc(x.image||productImg(p))}" alt="" title="Klik untuk memperbesar" style="width:44px;height:44px;object-fit:cover;border-radius:8px;cursor:zoom-in">`:''}<div class="grow">${esc([x.type,x.color,x.size].filter(Boolean).join(' · '))}<br><span class="muted">${x.stock>0?'Stok '+x.stock:'Habis'}</span></div><button type="button" class="secondary" data-step="-1" data-i="${i}" ${x.stock<=0?'disabled':''}>−</button><b id="vq${i}" style="min-width:22px;text-align:center">0</b><button type="button" class="secondary" data-step="1" data-i="${i}" ${x.stock<=0?'disabled':''}>+</button></div>`)}<div style="margin-top:10px">Total: <b id="oTotalTxt"></b></div>`;
 const upd=()=>{orderContext.qty.forEach((q,i)=>$('vq'+i).textContent=q);const n=orderContext.qty.reduce((a,b)=>a+b,0);$('oTotalTxt').textContent=money(p.price*n)+' ('+n+' pcs)';refreshTabBadges()};
 $('orderProductSummary').querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.i);orderContext.qty[i]=Math.max(0,Math.min(p.variants[i].stock,orderContext.qty[i]+Number(b.dataset.step)));upd()});upd();
 $('orderStatus').textContent='';drawPayChoices();$('orderModal').classList.add('show')}
$('orderForm').addEventListener('submit',async e=>{e.preventDefault();if(!sb)return;const st=$('orderStatus');st.style.color='var(--red)';const p=getProduct($('oProductId').value);const items=p?p.variants.map((x,i)=>({variant_id:x.id,qty:orderContext.qty?.[i]||0,i})).filter(t=>t.qty>0):[];
 if(!p||!items.length){st.textContent='Pilih minimal 1 variasi.';return}
 if(items.some(t=>p.variants[t.i].stock<t.qty)){st.textContent='Stok saat ini tidak mencukupi.';return}
 if(!/^[+0-9][0-9 \-]{7,17}$/.test($('oPhone').value.trim())){st.textContent='Nomor HP/WhatsApp tidak valid.';return}
 if(!$('oAddress').value.trim()){st.textContent='Alamat wajib diisi.';return}
 const pm=document.querySelector('input[name=payM]:checked')?.value;if(!pm){st.textContent='Pilih metode pembayaran.';return}
 const phoneV=$('oPhone').value.trim();const snap={customer:$('oCustomer').value.trim(),address:$('oAddress').value.trim(),note:$('oNote').value.trim(),productName:p.name,lines:items.map(t=>{const v=p.variants[t.i];return [v.group,v.type,v.color].filter(Boolean).join(' / ')+' × '+t.qty}),createdAt:new Date().toISOString()};const fromAdmin=SS.getItem('kabauria_sales_admin')==='1',ref=SS.getItem('kabauria_referral_session')||'';
 const btn=$('orderForm').querySelector('button[type=submit]');btn.disabled=true;st.textContent='Mengirim pesanan...';
 try{const {data,error}=await sb.rpc('create_order',{p_product_id:p.id,p_items:items.map(t=>({variant_id:t.variant_id,qty:t.qty})),p_customer:$('oCustomer').value.trim(),p_phone:$('oPhone').value.trim(),p_address:$('oAddress').value.trim(),p_note:$('oNote').value.trim(),p_payment:pm,p_ref_code:fromAdmin?null:(ref||null),p_source:fromAdmin?'admin':'direct'});if(error)throw error;
  $('orderForm').reset();$('orderModal').classList.remove('show');st.textContent='';showPayInfo({orderNo:data.order_no,total:Number(data.total),paymentMethod:data.payment_method,phone:phoneV,...snap});await refresh()}
 catch(err){st.textContent=err.message||'Gagal membuat pesanan.'}finally{btn.disabled=false}
});
function drawPayChoices(){const P=db.settings.payments,L={qris:'QRIS (scan gambar)',transfer:'Transfer bank (salin nomor rekening)',cash:'Tunai (bayar langsung)'};const on=Object.keys(L).filter(k=>P[k]?.enabled);$('oPayMethods').innerHTML=on.length?on.map((k,i)=>`<label class="payopt"><input type="radio" name="payM" value="${k}" ${i?'':'checked'}> ${L[k]}</label>`).join(''):'<div class="muted">Belum ada metode pembayaran aktif. Hubungi admin.</div>'}

/* ---------- Gambar data pesanan (disimpan pelanggan) ---------- */
function makeOrderImage(o){
 const P=db.settings.payments,W=720,PAD=40,big=document.createElement('canvas');big.width=W;big.height=3200;const c=big.getContext('2d');
 const SANS='system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif',SERIF='Georgia,"Times New Roman",serif';
 c.fillStyle='#fffdf7';c.fillRect(0,0,W,3200);
 const wrap=(t,x,y,maxW,lh)=>{const words=String(t).split(/\s+/);let line='';for(const w of words){const test=line?line+' '+w:w;if(c.measureText(test).width>maxW&&line){c.fillText(line,x,y);y+=lh;line=w}else line=test}c.fillText(line,x,y);return y+lh};
 // header
 const g=c.createLinearGradient(0,0,W,0);g.addColorStop(0,'#b0892a');g.addColorStop(1,'#6e500a');c.fillStyle=g;c.fillRect(0,0,W,120);
 c.fillStyle='#fff';c.font='700 34px '+SERIF;c.textBaseline='alphabetic';c.fillText('KABAURIA Kaos Tambang',PAD,56);
 c.font='600 18px '+SANS;c.fillStyle='#f6e5b0';c.fillText('BUKTI PESANAN',PAD,90);
 let y=170;
 c.fillStyle='#6b5a2a';c.font='600 16px '+SANS;c.fillText('Nomor pesanan',PAD,y);y+=40;
 c.fillStyle='#17130c';c.font='700 40px '+SANS;c.fillText(o.orderNo,PAD,y);y+=30;
 c.fillStyle='#6b5a2a';c.font='400 16px '+SANS;c.fillText(new Date(o.createdAt||Date.now()).toLocaleString('id-ID',{dateStyle:'long',timeStyle:'short'}),PAD,y);y+=30;
 const hr=()=>{c.strokeStyle='#e6d3a0';c.lineWidth=2;c.beginPath();c.moveTo(PAD,y);c.lineTo(W-PAD,y);c.stroke();y+=34};
 const row=(k,v)=>{c.fillStyle='#8a7a4a';c.font='600 15px '+SANS;c.fillText(k,PAD,y);y+=26;c.fillStyle='#17130c';c.font='500 20px '+SANS;y=wrap(v||'-',PAD,y,W-PAD*2,28)+10};
 hr();row('Nama pelanggan',o.customer);row('Nomor HP / WhatsApp',o.phone);row('Alamat pengiriman',o.address);if(o.note)row('Catatan',o.note);
 hr();
 c.fillStyle='#8a7a4a';c.font='600 15px '+SANS;c.fillText('Produk',PAD,y);y+=28;
 c.fillStyle='#17130c';c.font='700 22px '+SANS;y=wrap(o.productName||'-',PAD,y,W-PAD*2,30)+4;
 c.font='500 19px '+SANS;c.fillStyle='#3a3320';(o.lines||[]).forEach(l=>{y=wrap('• '+l,PAD+6,y,W-PAD*2-6,27)});y+=14;
 // total
 c.fillStyle='#f6ecc9';const bh=84;c.beginPath();c.roundRect?c.roundRect(PAD,y,W-PAD*2,bh,16):c.rect(PAD,y,W-PAD*2,bh);c.fill();
 c.fillStyle='#6b5a2a';c.font='600 16px '+SANS;c.fillText('Total bayar',PAD+22,y+34);
 c.fillStyle='#6e500a';c.font='700 34px '+SERIF;c.textAlign='right';c.fillText(money(o.total),W-PAD-22,y+60);c.textAlign='left';y+=bh+34;
 // pembayaran
 c.fillStyle='#8a7a4a';c.font='600 15px '+SANS;c.fillText('Metode pembayaran',PAD,y);y+=28;
 c.fillStyle='#17130c';c.font='700 22px '+SANS;c.fillText(payLabel(o.paymentMethod),PAD,y);y+=34;
 c.font='500 19px '+SANS;c.fillStyle='#3a3320';
 if(o.paymentMethod==='transfer'){y=wrap((P.transfer.bank||'')+' · a.n. '+(P.transfer.holder||''),PAD,y,W-PAD*2,27);c.font='700 28px '+SANS;c.fillStyle='#17130c';c.fillText(P.transfer.number||'-',PAD,y+6);y+=44}
 else if(o.paymentMethod==='qris'){y=wrap('Scan kode QRIS dari toko, bayar sesuai total, lalu kirim bukti pembayaran ke admin.',PAD,y,W-PAD*2,27)+6}
 else{y=wrap(P.cash.note||'Bayar tunai langsung kepada admin atau affiliate yang melayani Anda.',PAD,y,W-PAD*2,27)+6}
 y+=10;hr();
 c.fillStyle='#6b5a2a';c.font='500 16px '+SANS;
 y=wrap('Gratis ongkir untuk pengiriman dalam kota. Untuk luar kota, ongkos kirim berlaku dan dikonfirmasi admin.',PAD,y,W-PAD*2,24)+6;
 y=wrap('Simpan gambar ini dan tunjukkan kepada admin sebagai bukti pesanan. Pesanan diproses setelah pembayaran diverifikasi.',PAD,y,W-PAD*2,24)+16;
 const out=document.createElement('canvas');out.width=W;out.height=Math.ceil(y+PAD/2);out.getContext('2d').drawImage(big,0,0);
 return out}
function saveOrderImage(o){const cv=makeOrderImage(o);const url=cv.toDataURL('image/png');const fn='Pesanan-'+o.orderNo+'.png';
 const a=document.createElement('a');a.href=url;a.download=fn;document.body.appendChild(a);a.click();a.remove();
 const box=$('orderImgPreview');if(box)box.innerHTML='<img src="'+url+'" alt="Gambar pesanan" style="width:100%;max-width:360px;border:1px solid var(--line);border-radius:12px;margin-top:10px"><div class="muted">Jika gambar tidak otomatis tersimpan, tekan lama pada gambar lalu pilih Simpan gambar.</div>'}
function showPayInfo(o){const P=db.settings.payments;let h=`<div class="commission-box"><div class="muted">Nomor pesanan</div><div class="big">${esc(o.orderNo)}</div><div class="muted">Total bayar: <b>${money(o.total)}</b> · Metode: <b>${payLabel(o.paymentMethod)}</b></div></div><div style="margin-top:14px">`;
 if(o.paymentMethod==='qris')h+=P.qris.image?`<h3>Scan QRIS</h3><img src="${esc(P.qris.image)}" alt="QRIS" style="max-width:100%;width:300px;border:1px solid var(--line);border-radius:12px"><p class="muted">Bayar sesuai total, simpan bukti, lalu hubungi admin.</p>`:'<div class="empty">Gambar QRIS belum diunggah admin. Hubungi admin.</div>';
 else if(o.paymentMethod==='transfer')h+=`<h3>Transfer bank</h3><div class="commission-box"><div class="muted">${esc(P.transfer.bank)} · a.n. ${esc(P.transfer.holder)}</div><div class="big">${esc(P.transfer.number)}</div></div><button id="copyRek" style="margin-top:10px">Salin nomor rekening</button>`;
 else h+=`<h3>Bayar tunai</h3><p>${esc(P.cash.note)}</p>`;
 const others=['qris','transfer','cash'].filter(k=>k!==o.paymentMethod&&P[k]?.enabled);
 const sw=(others.length&&o.phone)?`<div class="notice" style="margin-top:14px"><b>Ingin ganti metode pembayaran?</b><div class="actions" style="margin-top:8px">${others.map(k=>`<button type="button" class="secondary" data-chpay="${k}">Ganti ke ${payLabel(k)}</button>`).join('')}</div><div id="chpayStatus" class="status"></div></div>`:'';
 const sv=o.customer?'<div style="margin-top:14px"><button type="button" id="saveOrderImg" class="success">Simpan gambar pesanan</button><div id="orderImgPreview"></div></div>':'';
 $('payBody').innerHTML=h+'</div>'+sv+sw+'<p class="muted">Admin akan memverifikasi pembayaran dan memproses pesanan Anda. Simpan nomor pesanan di atas.</p>';if($('saveOrderImg'))$('saveOrderImg').onclick=()=>saveOrderImage(o);
 $('payBody').querySelectorAll('[data-chpay]').forEach(b=>b.onclick=async()=>{const st=$('chpayStatus');st.style.color='var(--muted,#666)';st.textContent='Mengubah...';b.disabled=true;const {data,error}=await sb.rpc('change_payment_method',{p_order_no:o.orderNo,p_phone:o.phone,p_method:b.dataset.chpay});if(error){b.disabled=false;st.style.color='var(--red)';st.textContent=error.message;return}showPayInfo({...o,paymentMethod:data.payment_method,total:Number(data.total)||o.total});refresh()});
 if($('copyRek'))$('copyRek').onclick=()=>copyText(P.transfer.number,'Nomor rekening disalin.');$('payModal').classList.add('show')}

/* ---------- Login ---------- */
function resetSession(){session.admin=false;session.aff=''}
function loginForm(k){const ad=k==='admin';return `<div class="commission-box" style="max-width:380px;margin:auto"><h3>${ad?'Login Admin':'Login Affiliate'}</h3><div class="field"><label>${ad?'Email':'Username'}</label><input id="lgUser_${k}" type="text" ${ad?'inputmode="email"':''} autocapitalize="none" autocorrect="off" spellcheck="false" autocomplete="username"></div><div class="field" style="margin-top:10px"><label>Password</label><input id="lgPass_${k}" type="password" autocomplete="current-password"></div><button id="lgBtn_${k}" style="width:100%;margin-top:12px">Masuk</button><div id="lgSt_${k}" class="status" style="color:var(--red)"></div><div class="muted" style="font-size:11px;margin:4px 0">v${APP_VERSION}</div><div class="muted">${ad?'Akun admin dibuat di Supabase (lihat README).':'Username dan password dibuat oleh admin. Lupa password? Hubungi admin.'}</div></div>`}
function bindLogin(k){if(!sb){$('lgSt_'+k).textContent='Belum tersambung ke Supabase. '+cfgWhy;return}const st=$('lgSt_'+k);const val=()=>{const u=$('lgUser_'+k).value.trim();return{email:k==='aff'?(u.includes('@')?u:(u?userToEmail(u):'')):u,password:$('lgPass_'+k).value}};
 const done=async()=>{await refreshRole();
  if(k==='admin'&&!session.admin){await sb.auth.signOut();resetSession();st.style.color='var(--red)';st.textContent='Akun ini bukan admin.';return}
  if(k==='aff'&&!session.aff){const was=session.admin;await sb.auth.signOut();resetSession();st.style.color='var(--red)';st.textContent=was?'Akun admin: gunakan tab Dashboard admin.':'Akun ini belum aktif sebagai affiliate (mungkin masa aktif berakhir atau dinonaktifkan). Hubungi admin.';return}
  await refresh()};
 const go=async()=>{const {email,password}=val();st.style.color='var(--red)';if(!email||!password){st.textContent=k==='aff'?'Isi username dan password.':'Isi email dan password.';return}$('lgBtn_'+k).disabled=true;st.style.color='var(--muted,#666)';st.textContent='Memeriksa...';
  try{const {error}=await sb.auth.signInWithPassword({email,password});if(error){st.style.color='var(--red)';st.textContent=error.message==='Invalid login credentials'?(k==='aff'?'Username atau password salah.':'Email atau password salah.'):error.message;return}st.textContent='Berhasil, memuat data...';await done()}
  catch(err){st.style.color='var(--red)';st.textContent='Gagal: '+(err&&err.message||err);console.error(err)}
  finally{if($('lgBtn_'+k))$('lgBtn_'+k).disabled=false}};
 $('lgBtn_'+k).onclick=go;$('lgPass_'+k).addEventListener('keydown',e=>{if(e.key==='Enter')go()});}
async function logout(){await sb.auth.signOut();resetSession();await refresh()}

