 if(activeAdminView==='overview'){root.innerHTML=`<div class="stats"><div class="stat"><div class="label">Produk</div><div class="value">${db.products.length}</div></div><div class="stat"><div class="label">Affiliate aktif</div><div class="value">${active}</div><div class="sub">Masa aktif 6 bulan</div></div><div class="stat"><div class="label">Pesanan</div><div class="value">${db.orders.length}</div></div><div class="stat"><div class="label">Komisi siap dibayar</div><div class="value">${money(ready)}</div></div></div><div class="panel"><h3>Ringkasan alur kerja</h3><p class="muted">1. Kelola produk dan stok. 2. Tambah affiliate dan atur komisi. 3. Konfirmasi pembayaran pelanggan setelah memeriksa stok. 4. Tandai <b>Paket diterima</b> setelah pelanggan menerima barang; komisi affiliate baru masuk pada tahap ini. 5. Setujui komisi secara manual. 6. Transfer komisi dan catat pembayaran.</p><div class="notice">Jika pembayaran diterima tetapi stok tidak cukup, sistem menandai pesanan untuk penyelesaian admin. Lakukan refund bila diperlukan.</div></div><div class="panel"><h3>Aktivitas terbaru</h3>${db.audit.slice(0,8).map(l=>`<div class="affiliate-card"><div class="grow"><strong>${esc(l.action)}</strong><small>${esc(l.detail)} · ${new Date(l.date).toLocaleString('id-ID')}</small></div></div>`).join('')||'<div class="empty">Belum ada aktivitas.</div>'}</div>`}
 else if(activeAdminView==='products')renderProductsAdmin(root);
 else if(activeAdminView==='affiliates')renderAffiliatesAdmin(root);
